 @code {
     private List<Shipment>? shipments;
     private string filterText = string.Empty;
     private Dictionary<int, string> statusUpdates = new();
     private Shipment newShipment = new();

     private IEnumerable<Shipment> FilteredShipments => shipments!.Where(s =>
         string.IsNullOrWhiteSpace(filterText) ||
         s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
         s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

     protected override async Task OnInitializedAsync()
     {
         shipments = await ShipmentService.GetAllShipmentsAsync();
         foreach (var s in shipments)
         {
             statusUpdates[s.Id] = s.Status;
         }
     }

     private async Task UpdateStatus(int id)
     {
         if (statusUpdates.TryGetValue(id, out var status))
         {
             await ShipmentService.UpdateShipmentStatusAsync(id, status);
             shipments = await ShipmentService.GetAllShipmentsAsync();
             foreach (var s in shipments)
             {
                 statusUpdates[s.Id] = s.Status;
             }
         }
     }

     private async Task CreateShipment()
     {
         await ShipmentService.CreateShipmentAsync(newShipment);
         newShipment = new();
         shipments = await ShipmentService.GetAllShipmentsAsync();
         foreach (var s in shipments)
         {
             statusUpdates[s.Id] = s.Status;
         }
     }
 }

